let file = """{"version":3,"file":"usePartnerNodesRunGate-_XeBo7EM.js","names":[],"sources":["../../src/composables/node/usePartnerNodesInGraph.ts","../../src/composables/billing/usePartnerNodesRunGate.ts"],"sourcesContent":["import {\n  createSharedComposable,\n  tryOnScopeDispose,\n  useThrottleFn\n} from '@vueuse/core'\nimport { computed, ref, watch } from 'vue'\n\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { api } from '@/scripts/api'\nimport { useApp } from '@/scripts/appInstance'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { reduceAllNodes } from '@/utils/graphTraversalUtil'\n\nexport interface PartnerNodeInfo {\n  nodeName: string\n  displayName: string\n}\n\n/**\n * Scan the active graph (subgraphs included) for partner nodes right now,\n * deduped by def name. Synchronous and unthrottled so callers that gate a\n * queue decision see the current graph, not a throttled snapshot.\n */\nexport function scanPartnerNodesInGraph(): PartnerNodeInfo[] {\n  if (!useApp().isGraphReady) return []\n  const nodeDefStore = useNodeDefStore()\n  const partnerNodesByName = reduceAllNodes<Map<string, PartnerNodeInfo>>(\n    useApp().rootGraph,\n    (found, node) => {\n      const nodeDef = nodeDefStore.fromLGraphNode(node)\n      if (nodeDef?.api_node) {\n        found.set(nodeDef.name, {\n          nodeName: nodeDef.name,\n          displayName: nodeDef.display_name || nodeDef.name\n        })\n      }\n      return found\n    },\n    new Map()\n  )\n  return [...partnerNodesByName.values()]\n}\n\n/**\n * Reactive list of partner nodes (node defs with `api_node: true`) in the\n * active graph, including nodes nested in subgraphs, deduped by def name.\n */\nexport const usePartnerNodesInGraph = createSharedComposable(() => {\n  const workflowStore = useWorkflowStore()\n\n  const graphVersion = ref(0)\n  // Leading + trailing: gate state reacts to a topology change immediately, yet\n  // a drag still re-scans at most twice per burst rather than every frame.\n  const bumpGraphVersion = useThrottleFn(\n    () => {\n      graphVersion.value++\n    },\n    200,\n    true,\n    true\n  )\n\n  const onGraphChanged = () => {\n    void bumpGraphVersion()\n  }\n  api.addEventListener('graphChanged', onGraphChanged)\n  tryOnScopeDispose(() => {\n    api.removeEventListener('graphChanged', onGraphChanged)\n  })\n  watch(\n    () => workflowStore.activeWorkflow,\n    () => {\n      void bumpGraphVersion()\n    }\n  )\n\n  const partnerNodes = computed<PartnerNodeInfo[]>(() => {\n    // Dependency on graphVersion: re-scan when the graph mutates.\n    void graphVersion.value\n    return scanPartnerNodesInGraph()\n  })\n\n  const hasPartnerNodes = computed(() => partnerNodes.value.length > 0)\n\n  return { partnerNodes, hasPartnerNodes }\n})\n","import { createSharedComposable } from '@vueuse/core'\nimport { computed, watch } from 'vue'\n\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport {\n  scanPartnerNodesInGraph,\n  usePartnerNodesInGraph\n} from '@/composables/node/usePartnerNodesInGraph'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { firebaseIdentity } from '@/platform/auth/firebaseIdentity'\nimport { isCloud } from '@/platform/distribution/types'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useApiKeyAuthStore } from '@/stores/apiKeyAuthStore'\nimport { useAuthStore } from '@/stores/authStore'\n\nimport type { PartnerNodeInfo } from '@/composables/node/usePartnerNodesInGraph'\n\ntype PartnerRunGate = 'sign-in' | 'none'\ntype ApiKeyAuthStore = ReturnType<typeof useApiKeyAuthStore>\n\n/**\n * A gate block has no server backstop, so every one is reported. The gate only\n * blocks when isLoggedIn is false, so the tags read the raw sessions instead:\n * either being true means a signed-in user was blocked (Sentry alert #16504).\n */\nfunction reportGateBlocked(\n  trigger: 'run-button' | 'auto-queue',\n  partnerNodes: PartnerNodeInfo[],\n  apiKeyStore: ApiKeyAuthStore\n) {\n  reportError(new Error(`Partner run gate blocked ${trigger}`), {\n    surface: 'billing',\n    errorType: 'partner_run_gate_blocked',\n    level: 'warning',\n    tags: {\n      trigger,\n      hasFirebaseSession: firebaseIdentity.currentUser() !== null,\n      hasStoredApiKey: Boolean(apiKeyStore.getApiKey()),\n      partnerNodeCount: partnerNodes.length\n    },\n    context: { partnerNodeTypes: partnerNodes.map((n) => n.nodeName) }\n  })\n}\n\n/**\n * A signed-in user reads as logged-out until Firebase resolves and a stored\n * API key validates; never gate on that transient state.\n */\nfunction isAuthResolving(apiKeyStore: ApiKeyAuthStore): boolean {\n  return (\n    !useAuthStore().isInitialized ||\n    (Boolean(apiKeyStore.getApiKey()) && !apiKeyStore.isAuthenticated)\n  )\n}\n\n/**\n * Synchronous, unthrottled gate for the queue boundary: true when a local\n * signed-out user's current graph contains partner nodes they cannot run.\n * Every auto-queue path consults this before submitting, so no throttled\n * reactive snapshot can let a gated graph slip through.\n */\nexport function partnerRunGateBlocksAutoQueue(): boolean {\n  if (isCloud) return false\n  if (!useFeatureFlags().flags.partnerRunGateEnabled) return false\n  const apiKeyStore = useApiKeyAuthStore()\n  if (isAuthResolving(apiKeyStore)) return false\n  const { isLoggedIn } = useCurrentUser()\n  if (isLoggedIn.value) return false\n  const partnerNodes = scanPartnerNodesInGraph()\n  if (partnerNodes.length === 0) return false\n  reportGateBlocked('auto-queue', partnerNodes, apiKeyStore)\n  return true\n}\n\n/**\n * Decides whether the local/desktop Run button must be replaced because the\n * graph contains partner nodes the user cannot run yet. Cloud has its own\n * billing-driven gating (CloudRunButtonWrapper) and always resolves 'none'.\n */\nexport const usePartnerNodesRunGate = createSharedComposable(() => {\n  if (isCloud) {\n    return {\n      gate: computed<PartnerRunGate>(() => 'none'),\n      partnerNodes: computed<PartnerNodeInfo[]>(() => [])\n    }\n  }\n\n  const { partnerNodes, hasPartnerNodes } = usePartnerNodesInGraph()\n  const { isLoggedIn } = useCurrentUser()\n  const { flags } = useFeatureFlags()\n  const apiKeyStore = useApiKeyAuthStore()\n\n  const gate = computed<PartnerRunGate>(() =>\n    flags.partnerRunGateEnabled &&\n    !isAuthResolving(apiKeyStore) &&\n    hasPartnerNodes.value &&\n    !isLoggedIn.value\n      ? 'sign-in'\n      : 'none'\n  )\n\n  watch(\n    gate,\n    (value) => {\n      if (value !== 'sign-in') return\n      reportGateBlocked('run-button', partnerNodes.value, apiKeyStore)\n    },\n    { immediate: true }\n  )\n\n  return { gate, partnerNodes }\n})\n"],"mappings":"gkBAuBA,SAAgB,yBAA6C,CAC3D,GAAI,CAAC,EAAO,CAAC,CAAC,aAAc,MAAO,CAAC,EACpC,IAAM,EAAe,EAAgB,EAerC,MAAO,CAAC,GAdmB,EACzB,EAAO,CAAC,CAAC,WACR,EAAO,IAAS,CACf,IAAM,EAAU,EAAa,eAAe,CAAI,EAOhD,OANI,GAAS,UACX,EAAM,IAAI,EAAQ,KAAM,CACtB,SAAU,EAAQ,KAClB,YAAa,EAAQ,cAAgB,EAAQ,IAC/C,CAAC,EAEI,CACT,EACA,IAAI,GAEK,CAAA,CAAmB,OAAO,CAAC,CACxC,CAMA,IAAa,EAAyB,MAA6B,CACjE,IAAM,EAAgB,EAAiB,EAEjC,EAAe,EAAI,CAAC,EAGpB,EAAmB,MACjB,CACJ,EAAa,OACf,EACA,IACA,GACA,EACF,EAEM,mBAAuB,CAC3B,EAAsB,CACxB,EACA,EAAI,iBAAiB,eAAgB,cAAc,EACnD,MAAwB,CACtB,EAAI,oBAAoB,eAAgB,cAAc,CACxD,CAAC,EACD,MACQ,EAAc,mBACd,CACJ,EAAsB,CACxB,CACF,EAEA,IAAM,EAAe,OAEnB,EAAkB,MACX,wBAAwB,EAChC,EAID,MAAO,CAAE,eAAc,gBAFC,MAAe,EAAa,MAAM,OAAS,CAE5C,CAAgB,CACzC,CAAC,EC5DD,SAAS,kBACP,EACA,EACA,EACA,CACA,EAAgB,MAAM,4BAA4B,GAAS,EAAG,CAC5D,QAAS,UACT,UAAW,2BACX,MAAO,UACP,KAAM,CACJ,UACA,mBAAoB,EAAiB,YAAY,IAAM,KACvD,gBAAiB,EAAQ,EAAY,UAAU,EAC/C,iBAAkB,EAAa,MACjC,EACA,QAAS,CAAE,iBAAkB,EAAa,IAAK,GAAM,EAAE,QAAQ,CAAE,CACnE,CAAC,CACH,CAMA,SAAS,gBAAgB,EAAuC,CAC9D,MACE,CAAC,EAAa,CAAC,CAAC,eACf,EAAQ,EAAY,UAAU,GAAM,CAAC,EAAY,eAEtD,CAQA,SAAgB,+BAAyC,CAEvD,GAAI,CAAC,EAAgB,CAAC,CAAC,MAAM,sBAAuB,MAAO,GAC3D,IAAM,EAAc,EAAmB,EACvC,GAAI,gBAAgB,CAAW,EAAG,MAAO,GACzC,G